async (page) => {
  const os = require('os');
  const { execSync } = require('child_process');

  let output = '';

  // Try ip addr command
  try {
    output += '=== ip addr show ===\n';
    output += execSync('ip addr show', { encoding: 'utf-8' });
    output += '\n';
  } catch (e) {
    output += 'ip addr failed: ' + e.message + '\n';
  }

  // Try ifconfig
  try {
    output += '\n=== ifconfig -a ===\n';
    output += execSync('ifconfig -a 2>&1', { encoding: 'utf-8' });
    output += '\n';
  } catch (e) {
    output += 'ifconfig failed: ' + e.message + '\n';
  }

  // Try ip link
  try {
    output += '\n=== ip link show ===\n';
    output += execSync('ip link show', { encoding: 'utf-8' });
    output += '\n';
  } catch (e) {
    output += 'ip link failed: ' + e.message + '\n';
  }

  // Node.js os.networkInterfaces() as fallback
  output += '\n=== os.networkInterfaces() (Node.js) ===\n';
  const interfaces = os.networkInterfaces();
  for (const [name, addrs] of Object.entries(interfaces)) {
    output += `\nInterface: ${name}\n`;
    for (const addr of addrs) {
      output += `  ${addr.family} address: ${addr.address}  netmask: ${addr.netmask}  internal: ${addr.internal}  mac: ${addr.mac}\n`;
    }
  }

  return output;
}
